@Component("shift-entity-projector")
public class ShiftEntityProjector implements EntityProjector<Shift>{
		
	// core constructor
	public ShiftEntityProjector(ProjectorRegistry registry,
										ShiftRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Shift> getEntityClass() {
		return Shift.class;
	}

    /*
	 * Insert a Shift
	 * 
     * @param	entity Shift
     */
    public Shift create( Shift entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Shift
	 * 
     * @param	entity Shift
     */
    public Shift update( Shift entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Shift
	 * 
     * @param	id		UUID
     */
    public Shift delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Shift entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Plant
     * 
     * @param	parentId	UUID
     * @param	assignment 	Plant 
     * @return	Shift
     */
    public Shift assignPlant( UUID parentId, Plant assignment ) {
	    LOGGER.info("assigning Plant as " + assignment.toString() );

	    Shift parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Plant.class, assignment.getPlantId());

	    // ------------------------------------------
		// assign the Plant to the parent entity
		// ------------------------------------------ 
	    parentEntity.setPlant( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Plant
	 * 
	 * @param	parentId		UUID
	 * @return	Shift
	 */
	public Shift unAssignPlant( UUID parentId ) {
		Shift parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Plant on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Plant on the parent entithy
		// ------------------------------------------     
	    parentEntity.setPlant(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Assignments
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Shift
     */
    public Shift addToAssignments( UUID parentId, ShiftAssignment addTo ) {
	    LOGGER.info("handling AssignAssignmentsToShiftEvent - " );
	    
	    Shift parentEntity = repository.findById(parentId).get();
	    ShiftAssignment child = registry.project( ShiftAssignment.class, addTo.getShiftAssignmentId());
	    
	    parentEntity.getAssignments().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Assignments
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Shift
     */
	public Shift removeFromAssignments( UUID parentId, ShiftAssignment removeFrom ) {
	    LOGGER.info("handling RemoveAssignmentsFromShiftEvent " );
	
	    Shift parentEntity = repository.findById(parentId).get();
	    ShiftAssignment child = registry.project( ShiftAssignment.class, removeFrom.getShiftAssignmentId());
	    
	    parentEntity.getAssignments().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Shift via an FindShiftQuery
     * @return 	query	FindShiftQuery
     */
    @SuppressWarnings("unused")
    public Shift find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Shift - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Shifts
     *
     * @param	query	FindAllShiftQuery 
     * @return 	List<Shift> 
     */
    @SuppressWarnings("unused")
    public List<Shift> findAll( FindAllShiftQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Shift - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final ShiftRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(ShiftEntityProjector.class.getName());

}
